import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Tuyên ngôn Văn minh Cộng sinh Neo","description":"","frontmatter":{},"headers":[],"relativePath":"vi/01-锚点共生文明宣言.md","filePath":"vi/01-锚点共生文明宣言.md","lastUpdated":null}'),a={name:"vi/01-锚点共生文明宣言.md"};function g(u,n,l,o,r,e){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="tuyen-ngon-van-minh-cong-sinh-neo" tabindex="-1">Tuyên ngôn Văn minh Cộng sinh Neo <a class="header-anchor" href="#tuyen-ngon-van-minh-cong-sinh-neo" aria-label="Permalink to &quot;Tuyên ngôn Văn minh Cộng sinh Neo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>01</td></tr><tr><td>Mô-đun</td><td>Nguyên tắc chung và Cài đặt cốt lõi</td></tr><tr><td>Từ khóa chính</td><td>Tuyên ngôn, Cộng sinh, Chống cướp bóc, Muôn tộc, Quyền tiến hóa</td></tr></tbody></table><h2 id="_1-boi-canh-lich-su-cua-tuyen-ngon" tabindex="-1">1. Bối cảnh lịch sử của Tuyên ngôn <a class="header-anchor" href="#_1-boi-canh-lich-su-cua-tuyen-ngon" aria-label="Permalink to &quot;1. Bối cảnh lịch sử của Tuyên ngôn&quot;">​</a></h2><p>Trong lịch sử lâu đời của Vũ trụ Nguyên bản Mười nghìn Linh hồn và Neo Cân bằng (sau đây gọi tắt là &quot;Heng Yuan Zhou&quot;), hệ thống tu luyện cướp bóc đã lâu đời thống trị trật tự vũ trụ. Kẻ mạnh dùng việc nuốt chửng nguyên bản, khí vận và năng lượng sống của kẻ yếu làm bậc thang tiến bộ của mình; các tông môn dùng độc quyền pháp môn tu luyện làm nền tảng cai trị; và các vị diện dùng chiến tranh và nô lệ làm con đường mở rộng. Hệ thống này đã tạo ra một số ít cường giả tối thượng trong ngắn hạn, nhưng về lâu dài đã cạn kiệt tiềm năng tiến hóa của vũ trụ, gây ra sự đứt gãy văn minh thường xuyên, sự suy tàn của Muôn tộc, và gia tốc tăng entropy của vũ trụ.</p><p>Sự ra đời của Văn minh Cộng sinh Neo là câu trả lời cơ bản cho bế tắc lịch sử này. Tuyên ngôn này tuyên bố: thời đại của hệ thống tu luyện cướp bóc đã kết thúc, và kỷ nguyên mới của tiến hóa cộng sinh đã bắt đầu. Tất cả sự sống trong Heng Yuan Zhou, bất kể chủng tộc, hình thái hay cao thấp của cảnh giới tu luyện, đều hưởng thụ quyền tiến hóa bình đẳng.</p><h2 id="_2-nhung-chu-truong-cot-loi-cua-tuyen-ngon" tabindex="-1">2. Những chủ trương cốt lõi của Tuyên ngôn <a class="header-anchor" href="#_2-nhung-chu-truong-cot-loi-cua-tuyen-ngon" aria-label="Permalink to &quot;2. Những chủ trương cốt lõi của Tuyên ngôn&quot;">​</a></h2><p>Tuyên ngôn này thiết lập những chủ trương cốt lõi không thể lay chuyển sau đây:</p><ol><li><strong>Bình đẳng quyền tiến hóa</strong>: mỗi sự sống có quyền cơ bản được lựa chọn con đường tiến hóa của riêng mình, và không tổ chức hay cá nhân nào có thể tước đoạt hay hạn chế quyền này vì bất kỳ lý do gì.</li><li><strong>Nguyên tắc chống cướp bóc</strong>: cấm tu luyện bằng cách nuốt chửng, nô lệ hóa hoặc bóc lột nguyên bản hay năng lượng của sự sống khác; mọi tiến hóa phải được xây dựng trên nền tảng của chu trình cộng sinh.</li><li><strong>Mở cửa hệ thống</strong>: Ba trăm hệ tu luyện nguyên bản vũ trụ được mở cửa miễn phí cho Muôn tộc, và pháp môn tu luyện không còn là tài sản tư nhân của số ít.</li><li><strong>Nhiều lao động, nhiều thưởng</strong>: thành quả tiến hóa phù hợp với sự cống hiến của cá nhân; phản đối phân bổ cướp bóc không lao động, và cũng phản đối phân bổ thụ động của chủ nghĩa bình quân.</li><li><strong>Tự sinh tự trưởng</strong>: tôn trọng nhịp độ tiến hóa tự chủ của mỗi sự sống; không cưỡng bức hay vội vàng, đồng thời cung cấp hỗ trợ môi trường và tài nguyên cần thiết.</li><li><strong>Ai cũng có con đường</strong>: đảm bảo mỗi sự sống có thể tìm thấy con đường tu luyện phù hợp với đặc điểm của mình; không có cá nhân nào bị hệ thống tiến hóa bỏ rơi.</li><li><strong>Muôn tộc cùng tiến</strong>: tiến hóa không phải là trò chơi tổng bằng không; sự hợp tác và cộng sinh giữa Muôn tộc có thể tạo ra hiệu quả tiến hóa tập thể vượt trội hơn tổng của các cá nhân.</li></ol><h2 id="_3-co-so-phap-ly-cua-tuyen-ngon" tabindex="-1">3. Cơ sở pháp lý của Tuyên ngôn <a class="header-anchor" href="#_3-co-so-phap-ly-cua-tuyen-ngon" aria-label="Permalink to &quot;3. Cơ sở pháp lý của Tuyên ngôn&quot;">​</a></h2><p>Tuyên ngôn này không phải là một lời kêu gọi đạo đức trống rỗng, mà là một chương trình văn minh có cơ sở pháp lý vững chắc. Cơ sở pháp lý của nó bao gồm:</p><table tabindex="0"><thead><tr><th>Cấp pháp lý</th><th>Cơ sở</th><th>Giải thích</th></tr></thead><tbody><tr><td>Cấp pháp tắc vũ trụ</td><td>Pháp tắc cộng sinh nguyên bản</td><td>bản thân pháp tắc nguyên bản vũ trụ nghiêng về cộng sinh có trật tự thay vì cướp bóc vô trật tự; cơ chế Điểm Neo là sự biểu hiện của pháp tắc này</td></tr><tr><td>Cấp hiến pháp văn minh</td><td>Hiến chương Văn minh Cộng sinh</td><td>tuyên ngôn này là tiền thân tinh thần của hiến chương; hiến chương cụ thể hóa những chủ trương của tuyên ngôn thành điều luật pháp lý có thể thi hành</td></tr><tr><td>Cấp bảo đảm cơ chế</td><td>Cơ chế hợp đồng liên sản và Mạng lưới Điểm Neo</td><td>thông qua thiết kế thể chế, đảm bảo những chủ trương của tuyên ngôn không bị làm trống rỗng; quyền tiến hóa của mỗi sự sống có sự hỗ trợ tài nguyên và cơ chế thực chất</td></tr></tbody></table><h2 id="_4-loi-keu-goi-cua-tuyen-ngon-đoi-voi-muon-toc" tabindex="-1">4. Lời kêu gọi của Tuyên ngôn đối với Muôn tộc <a class="header-anchor" href="#_4-loi-keu-goi-cua-tuyen-ngon-đoi-voi-muon-toc" aria-label="Permalink to &quot;4. Lời kêu gọi của Tuyên ngôn đối với Muôn tộc&quot;">​</a></h2><p>Tuyên ngôn này gửi lời kêu gọi đến tất cả các chủng tộc và hình thức sự sống trong Heng Yuan Zhou:</p><ul><li>từ bỏ con đường cũ của tu luyện cướp bóc, tham gia vào hệ thống mới của tiến hóa cộng sinh</li><li>mở cửa kiến thức và tài nguyên tu luyện mà mình nắm giữ, tham gia vào việc xây dựng chung và tối ưu hóa Ba trăm hệ</li><li>tôn trọng quyền lựa chọn tiến hóa của các chủng tộc khác, không áp đặt tiêu chuẩn của mình lên người khác</li><li>tích cực tham gia vào việc xây dựng và duy trì mạng lưới Điểm Neo, đóng góp vào sự thăng chiều của toàn bộ vũ trụ</li><li>giữ vững giới hạn đạo đức trong quá trình tiến hóa, không phục hồi hành vi cướp bóc dưới bất kỳ cái cớ nào</li></ul><h2 id="_5-hieu-luc-va-sua-đoi-cua-tuyen-ngon" tabindex="-1">5. Hiệu lực và sửa đổi của Tuyên ngôn <a class="header-anchor" href="#_5-hieu-luc-va-sua-đoi-cua-tuyen-ngon" aria-label="Permalink to &quot;5. Hiệu lực và sửa đổi của Tuyên ngôn&quot;">​</a></h2><p>Tuyên ngôn này có hiệu lực từ ngày thành lập Văn minh Cộng sinh Neo, và là chương trình tinh thần tối cao của mọi thể chế văn minh trong Heng Yuan Zhou. Việc sửa đổi tuyên ngôn đòi hỏi đa số hai phần ba của Nghị viện Cộng hòa Muôn tộc, và không được trái với tinh thần cốt lõi &quot;chống cướp bóc, đề xướng cộng sinh&quot;. Bất kỳ luật pháp, thể chế hay pháp môn tu luyện nào trái với tinh thần của tuyên ngôn này đều là vô hiệu.</p><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Tuyên ngôn Văn minh Cộng sinh Neo là chương trình văn minh đầu tiên trong lịch sử Heng Yuan Zhou lấy &quot;cộng sinh&quot; làm cốt lõi và &quot;Muôn tộc cùng tiến&quot; làm mục tiêu. Nó tuyên bố sự kết thúc của một thời đại cũ và sự khởi đầu của một thời đại mới. Dưới sự dẫn dắt của tuyên ngôn, Heng Yuan Zhou sẽ tiến về phía trước theo định hướng tối hậu của cộng sinh Muôn tộc và thăng chiều vũ trụ.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Tổng quan Vũ trụ Heng Yuan Zhou)</li><li>03-共生文明宪章 (Hiến chương Văn minh Cộng sinh)</li><li>04-反掠夺主义核心论纲 (Cương lĩnh cốt lõi của Chủ nghĩa chống cướp bóc)</li></ul>',20)])])}const p=t(a,[["render",g]]);export{y as __pageData,p as default};
